export type SearchSuggestionSource='history'|'topic'|'related';
export type SearchSuggestion={term:string;source:SearchSuggestionSource;score:number};
export type SearchCatalogEntry={term:string;relevance:number};
export type SearchHistoryEntry={query:string;times_searched:number;last_searched_at:string};
export type SearchTopicEntry={term:string;count:number};

// Offline lexical fallback is explicitly ranked, not generated by a language model.
export const SEARCH_FALLBACK:readonly SearchCatalogEntry[]=[
 {term:'美女',relevance:150},{term:'美少女',relevance:140},{term:'美人',relevance:135},
 {term:'美食',relevance:131},{term:'美妆',relevance:130},{term:'美景',relevance:120},
 {term:'美术',relevance:110},{term:'美甲',relevance:104},{term:'美丽',relevance:101},
 {term:'动漫',relevance:110},{term:'游戏',relevance:108},{term:'电影',relevance:106},
 {term:'星流',relevance:110},{term:'科技',relevance:105},{term:'AI搜索',relevance:104},
];
export function extractRecentHashtags(contents:readonly string[],prefix:string):SearchTopicEntry[]{
 const key=prefix.trim().replace(/^#/,'').toLocaleLowerCase();
 const counts=new Map<string,number>();
 for(const body of contents){
  const tags=new Set<string>();
  for(const match of body.matchAll(/#([\p{L}\p{N}_]{1,32})/gu)) {
   const tag=match[1];
   if(tag.toLocaleLowerCase().startsWith(key))tags.add(tag);
  }
  for(const tag of tags)counts.set(tag,(counts.get(tag)||0)+1);
 }
 return [...counts].map(([term,count])=>({term,count}))
  .sort((a,b)=>b.count-a.count||a.term.localeCompare(b.term)).slice(0,20);
}
export function buildAISuggestions(
 input:string,catalog:readonly SearchCatalogEntry[],
 history:readonly SearchHistoryEntry[],topics:readonly SearchTopicEntry[],maxItems=8,
):SearchSuggestion[]{
 const key=input.trim().replace(/^#/,'').toLocaleLowerCase();
 const bucket=new Map<string,SearchSuggestion>();
 function push(term:string,source:SearchSuggestionSource,score:number){
  const normalized=term.trim().toLocaleLowerCase();
  if(!normalized||normalized.length>48||!normalized.startsWith(key)||normalized===key)return;
  const previous=bucket.get(normalized);
  if(!previous||previous.score<score)bucket.set(normalized,{term,source,score});
 }
 // Recent, frequent personal queries beat generic word completion.
 for(const item of history){
  const age=Date.now()-new Date(item.last_searched_at).getTime();
  const freshness=Number.isFinite(age)&&age>=0?Math.max(0,40-Math.floor(age/86400000)):0;
  push(item.query,'history',330+Math.min(Math.max(item.times_searched,1)*9,90)+freshness);
 }
 for(const topic of topics)push('#'+topic.term,'topic',170+Math.min(topic.count*10,120));
 for(const item of catalog)push(item.term,'related',item.relevance);
 return [...bucket.values()].sort((a,b)=>b.score-a.score||a.term.localeCompare(b.term,'zh-CN'))
  .slice(0,Math.min(Math.max(maxItems,1),12));
}
